<?php

namespace Database\Seeders;

/** Seeds `projects` from database/seeders/data/projects.json (generated by scripts/export-seed-data.ts in the frontend repo). */
class ProjectsSeeder extends ContentSeederBase
{
    public const TABLE = 'projects';

    public function run(): void
    {
        if (! $this->tableReady(self::TABLE)) {
            return;
        }
        $images = ['cover_image' => 'projects'];
        $keyCol = $this->hasColumn(self::TABLE, 'slug') ? 'slug' : 'name_ar';

        foreach ($this->json('projects') as $row) {
            if (empty($row[$keyCol])) {
                continue;
            }
            $this->upsertFillEmpty(self::TABLE, [$keyCol => $row[$keyCol]], $row, $images);
        }

        $this->report(self::TABLE);
    }
}
